CREATE TABLE learning_events(id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES audit_cases(id) ON DELETE CASCADE,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,revision INTEGER NOT NULL,features TEXT NOT NULL,human_verified INTEGER NOT NULL,training_eligible INTEGER NOT NULL,sale_eligible INTEGER NOT NULL,created_at INTEGER NOT NULL,UNIQUE(case_id,revision));
CREATE INDEX learning_tenant ON learning_events(tenant_id,case_id,revision);

CREATE TRIGGER learning_case_insert AFTER INSERT ON audit_cases BEGIN INSERT INTO learning_events(id,case_id,tenant_id,revision,features,human_verified,training_eligible,sale_eligible,created_at) SELECT lower(hex(randomblob(16))),NEW.id,NEW.tenant_id,NEW.revision, json_object('engineVersion','audit-v1','coverage',json_extract(NEW.payload,'$.line'),'rowBand',CASE WHEN json_array_length(NEW.payload,CASE json_extract(NEW.payload,'$.line') WHEN 'wc' THEN '$.wc' ELSE '$.gl' END)=0 THEN 'none' WHEN json_array_length(NEW.payload,CASE json_extract(NEW.payload,'$.line') WHEN 'wc' THEN '$.wc' ELSE '$.gl' END)<10 THEN '1-9' WHEN json_array_length(NEW.payload,CASE json_extract(NEW.payload,'$.line') WHEN 'wc' THEN '$.wc' ELSE '$.gl' END)<50 THEN '10-49' ELSE '50+' END,'reviewCategory',COALESCE(json_extract(NEW.payload,'$.workflow.reviewCategory'),'unclassified'),'outcome',COALESCE(json_extract(NEW.payload,'$.workflow.outcome'),'pending')), CASE WHEN json_extract(NEW.payload,'$.fictional')=0 AND json_extract(NEW.payload,'$.workflow.outcomeVerified')=1 AND json_extract(NEW.payload,'$.workflow.outcome')!='pending' AND length(trim(json_extract(NEW.payload,'$.workflow.reviewer')))>0 AND length(trim(json_extract(NEW.payload,'$.workflow.outcomeSource')))>0 THEN 1 ELSE 0 END, CASE WHEN (NEW.export_eligible & 1)!=0 AND COALESCE((SELECT training FROM consent_events WHERE user_id=t.owner_id ORDER BY created_at DESC,rowid DESC LIMIT 1),0)=1 THEN 1 ELSE 0 END, CASE WHEN (NEW.export_eligible & 2)!=0 AND COALESCE((SELECT sale FROM consent_events WHERE user_id=t.owner_id ORDER BY created_at DESC,rowid DESC LIMIT 1),0)=1 THEN 1 ELSE 0 END,unixepoch() FROM tenants t WHERE t.id=NEW.tenant_id; END;

CREATE TRIGGER learning_case_update AFTER UPDATE OF payload ON audit_cases BEGIN INSERT INTO learning_events(id,case_id,tenant_id,revision,features,human_verified,training_eligible,sale_eligible,created_at) SELECT lower(hex(randomblob(16))),NEW.id,NEW.tenant_id,NEW.revision, json_object('engineVersion','audit-v1','coverage',json_extract(NEW.payload,'$.line'),'rowBand',CASE WHEN json_array_length(NEW.payload,CASE json_extract(NEW.payload,'$.line') WHEN 'wc' THEN '$.wc' ELSE '$.gl' END)=0 THEN 'none' WHEN json_array_length(NEW.payload,CASE json_extract(NEW.payload,'$.line') WHEN 'wc' THEN '$.wc' ELSE '$.gl' END)<10 THEN '1-9' WHEN json_array_length(NEW.payload,CASE json_extract(NEW.payload,'$.line') WHEN 'wc' THEN '$.wc' ELSE '$.gl' END)<50 THEN '10-49' ELSE '50+' END,'reviewCategory',COALESCE(json_extract(NEW.payload,'$.workflow.reviewCategory'),'unclassified'),'outcome',COALESCE(json_extract(NEW.payload,'$.workflow.outcome'),'pending')), CASE WHEN json_extract(NEW.payload,'$.fictional')=0 AND json_extract(NEW.payload,'$.workflow.outcomeVerified')=1 AND json_extract(NEW.payload,'$.workflow.outcome')!='pending' AND length(trim(json_extract(NEW.payload,'$.workflow.reviewer')))>0 AND length(trim(json_extract(NEW.payload,'$.workflow.outcomeSource')))>0 THEN 1 ELSE 0 END, CASE WHEN (NEW.export_eligible & 1)!=0 AND COALESCE((SELECT training FROM consent_events WHERE user_id=t.owner_id ORDER BY created_at DESC,rowid DESC LIMIT 1),0)=1 THEN 1 ELSE 0 END, CASE WHEN (NEW.export_eligible & 2)!=0 AND COALESCE((SELECT sale FROM consent_events WHERE user_id=t.owner_id ORDER BY created_at DESC,rowid DESC LIMIT 1),0)=1 THEN 1 ELSE 0 END,unixepoch() FROM tenants t WHERE t.id=NEW.tenant_id; END;
